def get_prime_dict(number: int) -> dict:
    """number: 2 or greater."""
    from collections import OrderedDict

    prime_dict = OrderedDict()
    j = 2
    prime_dict[j] = 0
    for i in range(2, number + 1):
        if all(i % j != 0 for j in list(prime_dict.keys())):
            prime_dict[i] = 0
    return prime_dict


def execute_prime_factorization(primes: dict, number: int):
    for key in list(primes.keys()):
        if number >= key:
            tmp = number
            while tmp >= key:
                if tmp % key == 0:
                    primes[key] += 1
                    tmp = int(tmp / key)
                else:
                    break
    return primes


