class SegTree:
    def __init__(self, a):
        self.n = len(a)
        self.depth = 0
        while 2**self.depth < self.n:
            self.depth += 1
        self.data = [0] * (2 ** (self.depth + 1) - 1)
        self.data[2 ** (self.depth) - 1 : 2 ** (self.depth) - 1 + self.n] = a[:]
        for i in range(2**self.depth - 2, -1, -1):
            self.data[i] = self.data[2 * i + 1] + self.data[2 * i + 2]

    def add(self, i, x):
        i += 2**self.depth - 1
        self.data[i] += x
