def multi_lcm(array: list) -> dict:
    """arrayのLCMを素因数分解の積の形として求める(ABC152-E)
    入出力例: [4, 18, 21] -> {2: 2, 3: 2, 7: 1}
    key, val = 素因数, 素因数の個数
    """
    pf = {}  # pf: prime_factor
    for num in array:
        for k in range(2, int(num**0.5) + 1):
            cnt = 0
            while num % k == 0:
                cnt += 1
                num //= k
            if cnt != 0:
                if k not in pf:
                    pf[k] = cnt
                else:
                    pf[k] = max(cnt, pf[k])
        if num != 1:
            if num not in pf:
                pf[num] = 1
    return pf


