def p_facto(n):
    ret = []
    nc = n
    for i in range(2, nc):
        if i * i > nc:
            break
        if n % i == 0:
            ex = 0
            while n % i == 0:
                ex += 1
                n //= i
            ret.append([i, ex])
    if n != 1:
        ret.append([n, 1])
    return ret


