    for t in range(T):
        for i in range(len(AB)):
            a, b = AB[i]
            if t >= a:
                dp[t][i] = max(dp[t - a][i - 1] + b, dp[t - 1][i], dp[t][i - 1])
            else:
                dp[t][i] = max(dp[t - 1][i], dp[t][i - 1])
    B = list(map(lambda x: x[1], AB))
    B.append(0)
    dp = dp[-1]
    dp.pop()
    ans = 0
    for i, v in enumerate(dp):
        ans = max(ans, v + max(B[i + 1 :]))
    return ans


