def bit_dp(N, Adj):
    dp = [[0] * N for i in range(1 << N)]
    # dp({0], 0) = 1 と初期化する
    dp[1][0] = 1
    for S in range(1 << N):
        for v in range(N):
            # v が S に含まれていないときはパスする
            if (S & (1 << v)) == 0:
                continue
            # sub = S - {v}
            sub = S ^ (1 << v)
            for u in range(N):
                # sub に u が含まれており、かつ u と v が辺で結ばれている
                if (sub & (1 << u)) and (Adj[u][v]):
                    dp[S][v] += dp[sub][u]
    ans = sum(dp[(1 << N) - 1][u] for u in range(1, N))
    return ans


