class Bit:
    def __init__(self, n):
        self.size = n
        self.tree = [0] * (n + 1)

    def sum(self, i):
        s = 0
        while i > 0:
            s += self.tree[i]
            i -= i & -i
        return s

    def add(self, i, x):
        while i <= self.size:
            self.tree[i] += x
            i += i & -i


def judge(x, lst, n):
    length = len(lst)
    all_pair = (length * (length - 1) // 2) + length
    lst_r = [-1 if i < x else 1 for i in lst]
