    count = 0
    for j, b in enumerate(lst_accum):
        count += bit.sum(lst_accum_sorted[b]) + (b >= 0)
        bit.add(lst_accum_sorted[b], 1)
    if count >= math.ceil(all_pair / 2):
        return True
    else:
        return False


