def prime_table(n):
    prime = [True] * (n + 1)
    prime[0], prime[1] = False, False
    for i in range(2, n + 1):
        if not prime[i]:
            continue
        j = 2 * i
        while j <= n:
            prime[j] = False
            j += i
    return prime


