def main():
    # d[i][j]は2頂点間i, j間の移動コストを格納, Vは頂点数
    def warshall_floyd(d, V):
        for k in range(V):
            for i in range(V):
                for j in range(V):
                    d[i][j] = min(d[i][j], d[i][k] + d[k][j])
        return d  # d[i][j]に頂点i, j間の最短距離を格納

    n, m, r = list(map(int, input().split()))
    R = list(map(int, input().split()))
