    for _ in range(m):
        a, b, c = list(map(int, input().split()))
        d[a - 1][b - 1] = c
        d[b - 1][a - 1] = c
    d = warshall_floyd(d, n)
    ans = 10**10
    ptr = list(itertools.permutations(R, len(R)))  # 順列列挙 5P3
    for i in ptr:
        tmp = 0
        for j in range(len(i) - 1):
            tmp += d[i[j]][i[j + 1]]
        ans = min(ans, tmp)
    print(ans)


