class UnionFind:
    # ｎは頂点数
    def __init__(self, n):
        self.parent = [-1] * n

    # aの属する集合の根を取得
    def root(self, a):
        if self.parent[a] < 0:
            return a
        self.parent[a] = self.root(self.parent[a])
        return self.parent[a]

    # aの属する集合の要素数を取得
    def size(self, a):
        return -self.parent[self.root(a)]

    # aとbをくっつける
    def connect(self, a, b):
        if self.root(a) == self.root(b):
            return False
        a = self.root(a)
        b = self.root(b)
        if self.size(a) < self.size(b):
            a, b = b, a
        self.parent[a] += self.parent[b]
        self.parent[b] = a
        return True


