class Solution:
    def dp(self, pos, sign):
        if pos == self.n - 1:
            if sign == 0:
                return +self.lst[pos]
            else:
                return -self.lst[pos]
        elif (pos, sign) in self.vis:
            return self.rcd[pos][sign]
        elif sign == 0:
            self.rcd[pos][sign] = max(
                self.dp(pos + 1, 0) + self.lst[pos], self.dp(pos + 1, 1) - self.lst[pos]
            )
            self.vis.add((pos, sign))
            return self.rcd[pos][sign]
        else:
            self.rcd[pos][sign] = max(
                self.dp(pos + 1, 0) - self.lst[pos], self.dp(pos + 1, 1) + self.lst[pos]
            )
            self.vis.add((pos, sign))
            return self.rcd[pos][sign]

    def run(self):
        self.n = int(eval(input()))
        self.lst = list(map(int, input().split()))
        self.rcd = [[0, 0] for _ in range(self.n)]
        self.vis = set()
