def BellmanFord(N, M, edges):
    d = [inf] * N
    d[0] = 0
    for i in range(N - 1):
        for (u, v, c) in edges:
            if d[u] + c < d[v]:
                d[v] = d[u] + c
    for i in range(N):
        for (u, v, c) in edges:
            if d[u] + c < d[v]:
                if v == N - 1:
                    return None
                d[v] = d[u] + c
    return d[N - 1]


