            S.add(i)
    # ここからトポロジカルソート
    L = []
    # 暫定セットが空になるまでループ
    while S:
        # 暫定セットから結果リストへ1つ入れる
        L.append(S.pop())
        # 確定させたノードから流出するノードでループ
        for node in outnodes[L[-1]]:
            # 流入ノード数を1減らす
            incnts[node] -= 1
            # 流入ノードが0なら暫定セットへ
            if incnts[node] == 0:
                S.add(node)
        # そのノードの順序確定時に答えの更新もやればループは減ると思う
        src = L[-1]
        for dest in nodes[src]:
            dp[dest] = max(dp[dest], dp[src] + 1)
    return L


