class Edge:
    def __init__(self, t, w):
        self.to = t
        self.ew = w


class Graph:
    def __init__(self, N):
        self.nw = [-1] * N
        self.al = [[] for i in range(N)]

    def add_edge(self, fr, to, weight):
        self.al[fr].append(Edge(to, weight))
        self.al[to].append(Edge(fr, -weight))

    def dfs(self, s, used):
        self.nw[s] = 0
        q = deque([s])
        used.add(s)
        while q:
            h = q.popleft()
            for e in self.al[h]:
                if e.to in used:
                    if self.nw[h] + e.ew != self.nw[e.to]:
                        return False
                    continue
                used.add(e.to)
                self.nw[e.to] = self.nw[h] + e.ew
                q.appendleft(e.to)
        return True


