    def __init__(self, faces):
        self.faces = faces
        self.t = faces[0]
        self.s = faces[1]
        self.e = faces[2]
        self.w = faces[3]
        self.n = faces[4]
        self.b = faces[5]

    def roll(self, drct):
        t_ = self.t
        s_ = self.s
        e_ = self.e
        w_ = self.w
        n_ = self.n
        b_ = self.b
        if drct == "S":
            self.t = n_
            self.s = t_
            self.n = b_
            self.b = s_
        elif drct == "N":
            self.t = s_
            self.s = b_
            self.n = t_
            self.b = n_
        elif drct == "E":
            self.t = w_
            self.e = t_
            self.w = b_
            self.b = e_
        elif drct == "W":
            self.t = e_
            self.e = b_
            self.w = t_
            self.b = w_
        else:
            return

    def rotate_right(self):
        s_ = self.s
        w_ = self.w
        n_ = self.n
        e_ = self.e
        self.s = e_
        self.w = s_
        self.n = w_
        self.e = n_

    def set_top(self, face):
        if self.t == face:
            return
        elif self.s == face:
            self.roll("N")
        elif self.e == face:
            self.roll("W")
        elif self.w == face:
            self.roll("E")
        elif self.n == face:
            self.roll("S")
        else:
            self.roll("N")
            self.roll("N")

    def get_right_face(self, f):
        if self.s == f:
            return self.e
        elif self.e == f:
            return self.n
        elif self.w == f:
            return self.s
        else:
            return self.w

    def is_identical(self, other):
        directions = "NWWEESEES"
        for direction in directions:
            for i in range(4):
                if self.is_matchall(other):
                    return True
                self.rotate_right()
            self.roll(direction)
        return False

    def is_identical_(self, other):
        if self.is_matchall(other):
            return True
        self.roll("S")
        if self.is_matchall(other):
            return True
        self.roll("N")
        self.roll("E")
        if self.is_matchall(other):
            return True
        self.roll("W")
        self.roll("W")
        if self.is_matchall(other):
            return True
        self.roll("E")
        self.roll("N")
        if self.is_matchall(other):
            return True
        self.roll("N")
        if self.is_matchall(other):
            return True
        self.roll("S")
        self.roll("S")
        self.roll("E")
        self.roll("E")
        if self.is_matchall(other):
            return True
        return False

    def is_matchall(self, other):
        if self.t != other.t:
            return False
        if self.s != other.s:
            return False
        if self.e != other.e:
            return False
        if self.w != other.w:
            return False
        if self.n != other.n:
            return False
        if self.b != other.b:
            return False
        return True


