def mod_pow(a, b, mod):
    bin_b = []
    while b:
        bin_b.append(b % 2)
        b >>= 1
    ret = 1
    for j in reversed(bin_b):
        ret = (ret * ret) % mod
        if j == 1:
            ret = (ret * a) % mod
    return ret


