def exEuclid(a, b):
    if b == 0:
        return (a, 1, 0)
    else:
        (dd, xx, yy) = exEuclid(b, a % b)
        return (dd, yy, xx - (a // b) * yy)


def mycomb(n, k, p):
    k = min(n - k, k)
    fact = 1
    finv = 1
    for i in range(k):
        fact = fact * (n - i) % p
        finv = finv * (i + 1) % p
    (d, x, y) = exEuclid(finv, p)
    return fact * x % p


