def error_print(*args):
    print(*args, file=sys.stderr)


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()
        error_print(e - s, "sec")
        return ret

    return wrap


@mt
def slv(N):
    se = N + 1 if N % 2 == 0 else N
    return list(filter(lambda x: x[0] + x[1] != se, combinations(range(1, N + 1), 2)))


