def check(x):
    nodes = [[] for i in range(N)]
    for i in range(M):
        # 辺x以外でグラフを構築する
        if i == x:
            continue
        a, b = edges[i]
        nodes[a].append(b)
        nodes[b].append(a)
    # BFSで到達確認
    que = deque([0])
    visited = [0] * N
    while que:
        u = que.popleft()
        if visited[u]:
            continue
        visited[u] = 1
        for v in nodes[u]:
            que.append(v)
    # 全ての辺に到達できたか
    return sum(visited) != N


