def bfs(V, s, t):
    q = deque([(0, s)])
    used = set()
    while q:
        dist, a = q.popleft()
        used.add(a)
        if a == t:
            break
        for b in V[a]:
            if b in used:
                continue
            q.append((dist + 1, b))
    if a != t:
        dist = -1
    else:
        dist = -1 if dist % 3 else dist // 3
    return dist


def dijkstra1(V, n, source):
    # O(ElogV)
    inf = float("inf")
    dist = [inf] * (n + 1)
    dist[source] = 0
    q = [(0, source)]
    while q:
        cost, u = heappop(q)
        if dist[u] < cost:
            continue
        for c, v in V[u]:
            if dist[v] > dist[u] + c:
                dist[v] = dist[u] + c
                heappush(q, (dist[v], v))
    return dist


