def osp(n: int, g: List[Tuple[int, int]]) -> int:
    v = [False] * n
    return dfs(0, v, n, g)


def dfs(i, v, n, g):
    v[i] = True
    if all(v):
        v[i] = False
        return 1
    cnt = 0
