def bit_DP(N, Adj):
    dp = [[0] * N for i in range(1 << N)]
    dp[1][0] = 1
    for S in range(1 << N):
        for v in range(N):
            if (S & (1 << v)) == 0:
                continue
            sub = S ^ (1 << v)
            for u in range(N):
                if (sub & (1 << u)) and (Adj[u][v]):
                    dp[S][v] += dp[sub][u]
    ans = sum(dp[(1 << N) - 1][u] for u in range(1, N))
    return ans


