mod = 1000000007


def solve():
    h, w, k = LI()
    dp = [[0] * w for _ in range(h + 1)]
    dp[0][0] = 1
    k -= 1
    f = [1, 1]
    for i in range(w):
        f.append(f[-1] + f[-2])
    for i in range(h):
        ni = i + 1
        for j in range(w):
            dpj = dp[i][j]
            nj = j + 1
            if nj < w:
                l = f[j]
