        visited = []
        low = [0] * s._n
        ord = [-1] * s._n
        ids = [0] * s._n
        # 再帰関数
        def dfs(self, v, now_ord, group_num):
            low[v] = ord[v] = now_ord
            now_ord += 1
            visited.append(v)
            if v in s.g:
