    return [i for i in range(n + 1) if is_prime[i]]


def prime_factor(n):
    """Return a list of prime factorization numbers of n"""
    res = []
    for i in range(2, int(n**0.5) + 1):
        while n % i == 0:
            res.append(i)
            n //= i
    if n != 1:
        res.append(n)
    return res


