        elif op == "S":
            self.label = {1: l[5], 2: l[1], 3: l[3], 4: l[4], 5: l[6], 6: l[2]}

    def yaw(self, op):
        l = self.label
        if op == "CW":
            self.label = {1: l[1], 2: l[3], 3: l[5], 4: l[2], 5: l[4], 6: l[6]}
        elif op == "CCW":
            self.label = {1: l[1], 2: l[4], 3: l[2], 4: l[5], 5: l[3], 6: l[6]}

