class UF:
    # 経路圧縮のみのunion find木
    def __init__(self, n):
        self.n = n
        self.parents = [-1] * (n + 1)  # 1-indexedにするために１個足している
        self.rnks = [0] * (n + 1)

    def find(self, n):
        if self.parents[n] < 0:
            return n
        else:
            self.parents[n] = self.find(self.parents[n])
            return self.parents[n]

    def union(self, a, b):
        a_par = self.find(a)
        b_par = self.find(b)
        if a_par == b_par:
            return
        if self.rnks[a_par] > self.rnks[b_par]:
            a_par, b_par = b_par, a_par
        if self.rnks[a_par] == self.rnks[b_par]:
            self.rnks[a_par] += 1
        self.parents[a_par] += self.parents[b_par]
        self.parents[b_par] = a_par

    def length(self, n):
        par = self.find(n)
        return abs(self.parents[par])

    def is_same(self, a, b):
        return self.find(a) == self.find(b)


