import math


def factoring(n, dict_count={}):
    sup = math.floor(pow(n, 1 / 2))
    n_new = n
    for i in range(2, sup + 1):
        if n % i == 0:
            n_new = n // i
            if i in dict_count:
                dict_count[i] += 1
            else:
                dict_count[i] = 1
            break
    if n == n_new:
        if n_new in dict_count:
            dict_count[n_new] += 1
        else:
            dict_count[n_new] = 1
        return sorted(list(dict_count.items()))
    return factoring(n_new, dict_count)


