class SegmentTree:
    def __init__(self, array, operator, identity_element):
        _len = len(array)
        self.__op = operator
        self.__size = 1 << (_len - 1).bit_length()
        self.__tree = (
            [identity_element] * self.__size
            + array
            + [identity_element] * (self.__size - _len)
        )
        self.__ie = identity_element
        for i in range(self.__size - 1, 0, -1):
            self.__tree[i] = operator(self.__tree[i * 2], self.__tree[i * 2 + 1])

    def update(self, i, v):
        i += self.__size
        self.__tree[i] = v
        while i:
            i //= 2
            self.__tree[i] = self.__op(self.__tree[i * 2], self.__tree[i * 2 + 1])

    def query(self, l, r):
        """[l, r)"""
        l += self.__size
        r += self.__size
        ret = self.__ie
        while l < r:
            if l & 1:
                ret = self.__op(ret, self.__tree[l])
                l += 1
            if r & 1:
                r -= 1
                ret = self.__op(ret, self.__tree[r])
            l //= 2
            r //= 2
        return ret

    def __getitem__(self, key):
        return self.__tree[key + self.__size]


@mt
def slv(N, A, Q):
    st = SegmentTree(A, add, 0)
    ans = []
    for q in Q:
        if q[0] == 0:
            _, p, x = q
            st.update(p, st[p] + x)
        else:
            _, l, r = q
            ans.append(st.query(l, r))
    return ans


