    N, X, Y = list(map(int, input().split()))
    X -= 1
    Y -= 1

    def dijkstra(start, n, edges):
        d = [INF] * n
        used = [False] * n
        d[start] = 0
        used[start] = True
        edgelist = []
        for edge in edges[start]:
            heappush(edgelist, edge)
        while edgelist:
            minedge = heappop(edgelist)
            if used[minedge[1]]:
                continue
            v = minedge[1]
            d[v] = minedge[0]
            used[v] = True
            for edge in edges[v]:
                if not used[edge[1]]:
                    heappush(edgelist, (edge[0] + d[v], edge[1]))
        return d

