    digit = len(str(n))
    N = str(n)
    k = int(N[0])
    if digit < 2:
        return 0
    else:
        if k < a:
            return 0
        elif k == a:
            if n % (10 ** (digit - 1)) < b * (10 ** (digit - 1) - 1) // 9:
                s = 0
            else:
                s = 1
            return subfunction(a, b, n % (10 ** (digit - 1))) + s
        elif a < k < b:
