        factList.append([2, cnt])
    m = int(math.sqrt(n)) + 1
    for i in range(3, m + 1, 2):
        cnt = 0
        while temp % i == 0:
            temp = temp // i
            cnt += 1
        if cnt > 0:
            factList.append([i, cnt])
        if temp == 1:
            break
    if temp > 1:
        factList.append([temp, 1])
    return factList


