def topologicalSort(g: list, deg: list):
    ret = []
    q = []
    for i, d in enumerate(deg):
        if not d:
            ret.append(i)
            q.append(i)
    while q:
        cur = q.pop(0)
        for nxt in g[cur]:
            deg[nxt] -= 1
            if not deg[nxt]:
                ret.append(nxt)
                q.append(nxt)
    return ret


