def recursive_square(n, m, p):
    """n**p (mod m)"""
    if p == 0:
        return 1 % m
    if p % 2 == 0:
        root = recursive_square(n, m, p // 2) % m
        return (root**2) % m
    else:
        return ((n % m) * recursive_square(n, m, p - 1)) % m


