def F(n, x):
    if n == 0:
        return 1
    if x <= n:
        return 0
    if x <= f(n - 1) + 1:
        return F(n - 1, x - 1)
    elif x == f(n - 1) + 2:
        return g(n - 1) + 1
    else:
