def findunit(edges, N):
    roots = [i for i in range(N)]
    for edge in edges:
        if roots[edge[0]] == roots[edge[1]]:
            continue
        prv_root = roots[edge[1]]
        for idx, root in enumerate(roots):
            if root == prv_root:
                roots[idx] = roots[edge[0]]
    return roots


