def shaku(K, lists):
    ans = 0
    SUMS = 0
    index = 0
    for l in range(len(lists)):
        while index < l or index < len(lists) and SUMS + lists[index] < K:
            SUMS += lists[index]
            index += 1
        ans += index - l
        SUMS -= lists[l]
    return ans


