def allptn(abc, ma, mb):
    inf = 10**9
    # a,b,cの全組合せを作る
    allabc = [(0, 0, 0)]
    for a, b, c in abc:
        n = len(allabc)
        for i in range(n):
            aa, bb, cc = allabc[i]
            allabc.append((aa + a, bb + b, cc + c))
    # 指標とコストの組合せにする
    # 指標が重複するときはコストが小さいほうだけ残す
    # 指標が0のときは前後半で組み合わせる必要がないので単独で答えを出しておく
    vc = {}
    ans = inf
    for a, b, c in allabc[1:]:
        val = a * mb - b * ma
        if val:
            pc = vc.setdefault(val, inf)
            if c < pc:
                vc[val] = c
        else:
            if c < ans:
                ans = c
    res = [(val, c) for val, c in sorted(vc.items())]
    return ans, res


