        self.top = self.left
        self.left = self.bottom
        self.bottom = self.right
        self.right = tmp

    def toW(self):
        tmp = self.top
        self.top = self.right
        self.right = self.bottom
        self.bottom = self.left
        self.left = tmp

    def moveTo(self, ds):
        for d in ds:
            if d == "N":
                self.toN()
            if d == "S":
                self.toS()
            if d == "E":
                self.toE()
            if d == "W":
                self.toW()

    def getTop(self):
