    return INPUT().split()


def solve(n, m):
    floors = [0] * (n + 1)
    floors[0] = 1
    floors[1] = 1
    last, current = 0, 0
    for i in range(m):
        if i == 0:
            current = SINGLE_INT()
            floors[current] = -1
        else:
            last = current
            current = SINGLE_INT()
            floors[current] = -1
            if current == last + 1:
                return 0
    for i in range(2, n + 1):
        if floors[i] == -1:
            continue
        else:
            if floors[i - 2] > 0:
                floors[i] += floors[i - 2]
            if floors[i - 1] > 0:
                floors[i] += floors[i - 1]
        floors[i] %= MOD
    return floors[-1]


