def eratosthenes(n):
    p = []  # n以下の素数リスト
    t = [-1] * n  # t_iの素因数の内最小のもの
    t[0] = 0
    t[1] = 0
    for i in range(2, ceil(sqrt(n))):
        if t[i] == -1:
            p.append(i)
            # t[i] = i
            for j in range(2 * i, n, i):
                if t[j] == -1:
                    t[j] = i
    for j in range(i + 1, n):
        if t[j] == -1:
            p.append(j)
            # t[j] = j
    return p, t


