            if l & 1:
                s = self.func(s, self.tree[l])
                l += 1
            l >>= 1
            r >>= 1
        return s

    def get(self, i):
        """一点取得"""
        return self.tree[i + self.n2]

    def all(self):
        """全区間[0, n)の取得"""
        return self.tree[1]


