state = [-1 for i in range(100010)]


def step_state(n, broken):
    if state[n] != -1:
        return state[n]
    if n == 0:
        state[0] = 1
        return 1
    elif n == 1:
        if broken[1]:
            state[1] = 0
            return 0
        else:
            state[1] = 1
            return 1
    else:
        if broken[n - 1] and broken[n - 2]:
            state[n] = 0
            return 0
        elif broken[n - 1]:
            state[n] = step_state(n - 2, broken) % MOD
            return state[n]
        elif broken[n - 2]:
            state[n] = step_state(n - 1, broken) % MOD
            return state[n]
        else:
            state[n] = (step_state(n - 1, broken) + step_state(n - 2, broken)) % MOD
            return state[n]


