                # kの数字広義単調増加にならない場合はcontinue
                if j > c:
                    continue
                # t:kを右端の操作済カードの次に並べるための操作回数
                # それは、初期配置でkより左にあってまだ操作済でないカードの枚数と一致する
                t = 0
                for l in range(k):
