def reachable_vertices(neighbor, s):
    V = set()
    V.add(s)
    stack = [s]
    while stack:
        v = stack.pop()
        for u in neighbor[v]:
            if u not in V:
                V.add(u)
                stack.append(u)
    return V


def neighbor_dict(E):
    neighbor = defaultdict(list)
    for a, b, c in E:
        neighbor[a].append(b)
    return neighbor


def rev_neighbor_dict(E):
