        a, _ = list(map(int, input().split()))
        c = sum([1 << (int(i) - 1) for i in input().split()])
        for s in range(p):
            t = s | c
            new = dp[s] + a
            if dp[t] > new:
                dp[t] = new
    ans = dp[-1]
    if ans == inf:
        ans = -1
    print(ans)


