def Bellman_Ford(g, start):
    n = len(g)
    dist = [float("inf")] * n
    dist[start] = 0
    a0 = float("inf")
    for i in range(n << 1):
        updated = False
        for v in range(n):
            for to, cost in g[v]:
                if dist[to] <= dist[v] + cost:
                    continue
                dist[to] = dist[v] + cost
                updated = True
        if not updated:
            break
        if i <= n:
            a0 = dist[-1]
    if a0 != dist[-1]:
        return None, False
    return dist, True


