def is_ok(a, key, idx):
    if a[idx] <= key:
        return True
    else:
        return False


def binary_search(a, key):
    """Meguru type binary search"""
    ok = -1
    ng = len(a)
    while abs(ok - ng) > 1:
        mid = (ok + ng) // 2
        if is_ok(a, key, mid):
            ok = mid
        else:
            ng = mid
    return ok


def main():
