import itertools


def count_chains(nums):
    it = iter(nums)
    try:
        previous = next(it)
    except StopIteration:
        return
    count = 1
    for n in it:
        if previous < n:
            yield count
            count = 0
        count += 1
        previous = n
    yield count


def main():
