class UnionFind:
    """UnionFind木"""

    def __init__(self, n):
        self.data = [-1] * n

    def unite(self, x, y):
        """x と y を結合"""
        x = self.find(x)
        y = self.find(y)
        if x == y:
            return
        elif self.data[x] < self.data[y]:
            x, y = y, x  # swap
        self.data[x] += self.data[y]
        self.data[y] = x

    def find(self, x):
        """ノード x の親を返す"""
        if self.data[x] < 0:
            return x
        self.data[x] = self.find(self.data[x])
        return self.data[x]

    def same(self, x, y):
        """x と y が同じグループに属するか判定"""
        return self.find(x) == self.find(y)

    def size(self, x):
        """x を含むグループのノード数を返す"""
        return self.data[self.find(x)]

    def indep(self):
        dep = 0
        for i in range(len(self.data)):
            if self.data[i] < 0:
                dep += 1
        return dep


