class uf_tree:
    def __init__(self, n):
        self.n = n
        self.par = [i for i in range(n)]

    def indep(self):
        dep = 0
        for i in range(self.n):
            if i == self.par[i]:
                dep += 1
        return dep

    def unite(self, child, mas):
        if self.root(child) == self.root(mas):
            return
        else:
            self.par[self.root(child)] = self.root(mas)

    def root(self, i):
        if self.par[i] == i:
            return i
        else:
            self.par[i] = self.root(self.par[i])
            return self.par[i]

    def same(self, x, y):
        if self.root(x) == self.root(y):
            return True
        else:
            return False


