def dijkstra(n, start):
    dist = [float("inf")] * n
    pos = [(0, start)]
    heapify(pos)
    dist[start] = 0
    while len(pos):
        cost, u = heappop(pos)
        if dist[u] < cost:
            continue
        # エッジは探索のたびに生成していく
        for i in range(len(coin)):
