def dijkstra(s):
    """
    始点sから各頂点への最短距離を求める
    """
    d = [float("inf")] * 10
    d[s] = 0
    used = [False] * 10
    used[s] = True
    edgelist = []
    for e in edge[s]:
        heappush(edgelist, e)
    while edgelist:
        cost, v = heappop(edgelist)
        if used[v]:
            continue
        d[v] = cost
        used[v] = True
        for e in edge[v]:
            if not used[e[1]]:
