def bellman_ford(n, edges, start):
    vertices = [inf] * n
    vertices[start] = 0
    reached = {start}
    for i in range(n):
        flag = 0
        for v in reached.copy():
            cost = vertices[v]
            for dist, _cost in edges[v]:
