class Mint:
    def __init__(self, value=0):
        self.value = value % MOD
        if self.value < 0:
            self.value += MOD

    @staticmethod
    def get_value(x):
        return x.value if isinstance(x, Mint) else x

    def inverse(self):
        a, b = self.value, MOD
        u, v = 1, 0
        while b:
            t = a // b
            b, a = a - t * b, b
            v, u = u - t * v, v
        if u < 0:
            u += MOD
        return u

    def __repr__(self):
        return str(self.value)

    def __eq__(self, other):
        return self.value == other.value

    def __neg__(self):
        return Mint(-self.value)

    def __hash__(self):
        return hash(self.value)

    def __bool__(self):
        return self.value != 0

