    done = set(p[len(p) // 2 - 1 :])
    d = {nu: 0}
    s = [nu]
    while s:
        u = s.pop()
        for v in g[u]:
            if v in done:
                continue
            d[v] = d[u] + 1
            done.add(u)
            s.append(v)
    return ans + max(d.values())


