class FenwickTree:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, i, x):
        i += 1
        while i <= n:
            self.bit[i] += x
            i += i & -i

    def sumsub(self, r):
        ans = 0
        while r:
            ans += self.bit[r]
            r -= r & -r
        return ans

    def sum(self, l, r):
        ans = self.sumsub(r)
        if l != 0:
            ans -= self.sumsub(l)
        return ans


