def half_rekkyo(N, Ma, Mb, table, s, m):
    res = dict()
    for comb in range(1, 2**m):
        v = 0
        cost = 0
        for i in range(m):
            if comb & (1 << i):
                a, b, c = table[s + i]
                v += b * Ma - a * Mb
                cost += c
        if v in res:
            res[v] = min(res[v], cost)
        else:
            res[v] = cost
    return res


