    """ """
    b = [0] * (N + 1)
    for i in range(N):
        b[i + 1] = b[i] + A[i]
    c = [x % M for x in b]
    return binomial_coefficients(c)
    # return loop(c)


def binomial_coefficients(c):
    from collections import Counter

    ans = 0
    for i, n in list(Counter(c).items()):
        ans += n * (n - 1) // 2
    return ans


