        m[x] += 1
    return ans


def TLE(N, M, A, b):
    ans = 0
    for l in range(N):
        for r in range(l, N):
            if l - 1 < 0:
                s = b[r]
            else:
                s = b[r] - b[l - 1]
            if s % M == 0:
                ans += 1
    return ans


