def rangemax(p, q):
    if q <= p:
        return -1
    p += num - 1
    q += num - 2
    res = -1
    while q - p > 1:
        if p & 1 == 0:
            res = max(res, MA[p])
        if q & 1 == 1:
            res = max(res, MA[q])
            q -= 1
        p = p // 2
        q = (q - 1) // 2
    if p == q:
        res = max(res, MA[p])
    else:
        res = max(max(res, MA[p]), MA[q])
    return res


