def error_print(*args):
    print(*args, file=sys.stderr)


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()
        error_print(e - s, "sec")
        return ret

    return wrap


@mt
def slv(H, W, S):
    def edges(v):
        i, j = v
        r = []
        if i > 0 and S[i - 1][j] == ".":
            r.append((i - 1, j))
        if i < H - 1 and S[i + 1][j] == ".":
            r.append((i + 1, j))
        if j > 0 and S[i][j - 1] == ".":
            r.append((i, j - 1))
        if j < W - 1 and S[i][j + 1] == ".":
            r.append((i, j + 1))
        return r

    def bfs(s):
        q = deque([s])
        d = {s: 0}
        while q:
            u = q.popleft()
            for v in edges(u):
                if v not in d:
                    d[v] = d[u] + 1
                    q.append(v)
        return max(d.values())

    ans = 0
    for i in range(H):
        for j in range(W):
            if S[i][j] == ".":
                l = bfs((i, j))
                ans = max(ans, l)
    return ans


