def restore_lcs(s, t, dp):
    lcs = ""
    i, j = len(s), len(t)
    while i >= 0 and j >= 0:
        if dp[i][j] == dp[i - 1][j]:
            i -= 1
            continue
        if dp[i][j] == dp[i][j - 1]:
            j -= 1
            continue
        lcs += s[i - 1]
        i -= 1
        j -= 1
    return lcs[::-1]


