    def __init__(self, n):
        self.size = n
        self.tree = [0 for _ in range(n + 1)]
        self.p = 2 ** (n.bit_length() - 1)
        self.dep = n.bit_length()

    def get(self, i):
        s = 0
        while i > 0:
            s += self.tree[i]
            i -= i & -i
        return s

