# UnionFind
class UnionFind:
    def __init__(self, n):
        self.n = n
        self.a = [-1] * n
        self.r = [0] * n
        self.siz = n

    def root_find(self, x):
        if self.a[x] < 0:
            return x
        else:
            self.a[x] = self.root_find(self.a[x])
            return self.a[x]

    def unite(self, x, y):
        x = self.root_find(x)
        y = self.root_find(y)
        if x == y:
            return
        if self.r[x] == self.r[y]:
            self.r[x] += 1
            self.a[x] += self.a[y]
            self.a[y] = x
        elif self.r[x] > self.r[y]:
            self.a[x] += self.a[y]
            self.a[y] = x
        else:
            self.a[y] += self.a[x]
            self.a[x] = y
        self.siz -= 1

    def root_same(self, x, y):
        return self.root_find(x) == self.root_find(y)


