    if n_min is None:
        n_min = min(A)
    if n_max is None:
        n_max = max(A)
    bin = [0] * (n_max - n_min + 1)
    for a in A:
        bin[a - n_min] += 1
    B = []
    for i in range(n_min, n_max + 1):
        B += [i] * bin[i - n_min]
    return B


