def lunlun_num(N):
    N = str(N)
    L = len(N)
    dp = [[0] * 10 for j in range(L)]
    for j in range(1, int(N[0])):
        dp[0][j] = 1
    flag = True
    for i in range(L - 1):
        d = int(N[i + 1])
        b = int(N[i])
        dp[i + 1][0] += dp[i][0] + dp[i][1]
        dp[i + 1][9] += dp[i][8] + dp[i][9]
        for j in range(1, 9):
            dp[i + 1][j] += dp[i][j - 1] + dp[i][j] + dp[i][j + 1]
        for j in range(1, 10):
            dp[i + 1][j] += 1
        if flag:
            if d < b - 1:
                flag = False
            elif d <= b + 1:
                for j in range(max(0, b - 1), d):
                    dp[i + 1][j] += 1
            else:
                for j in range(max(0, b - 1), b + 2):
                    dp[i + 1][j] += 1
                    flag = False
    return sum(dp[L - 1]) + 1 if flag else sum(dp[L - 1])


