def dijkstra(graph: list, start, INF=float("inf")) -> list:
    n = len(graph)
    dist = [INF] * n
    visited = [False] * n
    dist[start] = 0
    que = [(0, start)]
    while que:
        cost, cur = heappop(que)
        if visited[cur]:
