        [-1] * len(g),
        make_list(len(g), 0),
        [-1] * len(g),
        deque([start]),
    )
    depth[start] = 0
    while q:
        i = q.popleft()
        for j in g[i]:
            if depth[j] != -1:
                parent[i] = j
            else:
                depth[j] = depth[i] + 1
                children[i].append(j), q.append(j)
