def error_print(*args):
    print(*args, file=sys.stderr)


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()
        error_print(e - s, "sec")
        return ret

    return wrap


@mt
def slv(N, S):
    d = Counter()
    for s in S:
        d[tuple(sorted(s))] += 1
    return reduce(lambda x, y: x + (y * (y - 1)) // 2, d.values(), 0)


