def bit_dp(N, Adj):
    dp = [[0] * N for i in range(1 << N)]
    # dp[{0},0] = 1
    dp[1][0] = 1
    for S in range(1 << N):
        for v in range(N):
            # v がSに含まれていないときはパス
            if (S & (1 << v)) == 0:
                continue
            # sub = S - {v}
            sub = S ^ (1 << v)
            for u in range(N):
                # sub に uが含まれていて、かつ uとvがへんで結ばれている
                if (sub & (1 << u)) and (Adj[u][v]):
                    dp[S][v] += dp[sub][u]
    ans = sum(dp[(1 << N) - 1][u] for u in range(1, N))
    return ans


def main():
    N, M = list(map(int, input().split()))
    Adj = [[False] * N for _ in range(N)]
    for _ in range(M):
        a, b = list(map(int, input().split()))
        Adj[a - 1][b - 1] = 1
        Adj[b - 1][a - 1] = 1
    ans = bit_dp(N, Adj)
    print(ans)


