        return [i for i in range(self.n) if self.Find_Root(i) == self.Find_Root(x)]

    def Roots(self):  # 全ての根の要素をリストで返す
        return [i for i, x in enumerate(self.root) if x < 0]

    def Group_Count(self):  # グループの数を返す
        return len(self.Roots())


