            for k1, k2 in [(0, 0), (0, 1), (1, 0), (1, 1)]:
                pos1, pos2 = xy[i][k1], xy[j][k2]
                if abs(pos2 - pos1) < D:
                    ts.add_clause(i, k1 ^ 1, j, k2 ^ 1)
    if ts.satisfiable():
        print("Yes")
        print(*[xy[i][ts.ans[i]] for i in range(N)], sep="\n")
    else:
        print("No")


